#include <iostream>
#include <string>
#include <sstream>

int main() {
    std::string line;
    std::getline(std::cin, line);

    std::stringstream ss(line);
    int num;
    long long sum = 0;

    while (ss >> num) {
        sum += num;
    }

    if (sum > 0 && sum % 5 == 0) {
        std::cout << sum / 5 << std::endl;
    } else {
        std::cout << -1 << std::endl;
    }

    return 0;
}

